// Isolation test (OS-12) — construct ScopeLedger with its declared inputs and nothing else, then
// exercise every public operation. (Generated by new-object.py, rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { isUnknown, noSubject } from "../src/kernel/index.js";
import { ScopeLedger } from "../src/spend/index.js";
import { barOf, c0, forms, scopeWorld, u } from "./support/spend-parts.js";

const STOP = { kind: "stop-at-bar", component: "q" } as const;

function parts() {
  const { record, declarations } = scopeWorld();
  const h = record.noise();
  const form = forms.build(u, c0, h);
  if (isUnknown(form)) throw new Error("setup");
  return { record, declarations, bar: barOf(true), form, h };
}

describe("ScopeLedger in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    const { record, declarations, bar } = parts();
    const all = { record, declarations, bar };
    for (const missing of Object.keys(all)) expect(() => new ScopeLedger({ ...all, [missing]: undefined } as never), missing).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    const { record, declarations, bar } = parts();
    const all = { record, declarations, bar };
    for (const slot of Object.keys(all)) expect(() => new ScopeLedger({ ...all, [slot]: {} } as never), slot).toThrow();
  });

  it("authorize answers differently when record differs", () => {
    const one = parts();
    const two = parts();
    two.record.noise();
    const a = new ScopeLedger(one).authorize(one.form, 3, { kind: "none" }, "e", "HUMAN", one.h);
    const b = new ScopeLedger(two).authorize(one.form, 3, { kind: "none" }, "e", "HUMAN", one.h);
    expect(a).not.toEqual(b);
  });

  it("authorize answers differently when bar differs", () => {
    const p = parts();
    const a = new ScopeLedger(p).authorize(p.form, 3, STOP, "e", "HUMAN", p.h);
    const b = new ScopeLedger({ ...p, bar: barOf(false) }).authorize(p.form, 3, STOP, "e", "HUMAN", p.h);
    expect(a).not.toEqual(b);
  });

  it("authorize answers differently when declarations differs", () => {
    const p = parts();
    const a = new ScopeLedger(p).authorize(p.form, 3, STOP, "e", "HUMAN", p.h);
    const b = new ScopeLedger({ ...p, declarations: { declarationAt: () => noSubject() } }).authorize(p.form, 3, STOP, "e", "HUMAN", p.h);
    expect(a).not.toEqual(b);
  });
});
